import os,subprocess,hashlib
def inspect_format(repo,payload):
    env={k:v for k,v in os.environ.items() if not k.startswith('GIT_')};env.update(GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL=os.devnull,GIT_OPTIONAL_LOCKS='0',GIT_TERMINAL_PROMPT='0')
    def git(*args,data=None):
        p=subprocess.run(['git','--no-replace-objects','-C',str(repo),*args],input=data,env=env,capture_output=True,timeout=4)
        if p.returncode:raise RuntimeError('object format inspection failed')
        return p.stdout.decode('ascii').strip()
    fmt=git('rev-parse','--show-object-format')
    if fmt not in ('sha1','sha256'):raise ValueError('unsupported object format')
    computed=hashlib.new(fmt,b'blob '+str(len(payload)).encode()+b'\0'+payload).hexdigest()
    actual=git('hash-object','--stdin',data=payload)
    if actual!=computed:raise ValueError('object serialization/hash mismatch')
    return dict(format=fmt,head=git('rev-parse','HEAD'),blob=actual)
